function bsample(data,w,h,x,y){
  if(x<0)x=0; else if(x>w-1)x=w-1;
  if(y<0)y=0; else if(y>h-1)y=h-1;
  var x0=Math.floor(x), y0=Math.floor(y);
  var x1=x0+1, y1=y0+1;
  if(x1>w-1)x1=w-1; if(y1>h-1)y1=h-1;
  var fx=x-x0, fy=y-y0;
  var i00=(y0*w+x0)*4, i10=(y0*w+x1)*4, i01=(y1*w+x0)*4, i11=(y1*w+x1)*4;
  var o0=data[i00]+(data[i10]-data[i00])*fx;
  var o1=data[i01]+(data[i11]-data[i01])*fx;
  var r=o0+(o1-o0)*fy;
  var g0=data[i00+1]+(data[i10+1]-data[i00+1])*fx;
  var g1=data[i01+1]+(data[i11+1]-data[i01+1])*fx;
  var g=g0+(g1-g0)*fy;
  var b0=data[i00+2]+(data[i10+2]-data[i00+2])*fx;
  var b1=data[i01+2]+(data[i11+2]-data[i01+2])*fx;
  var b=b0+(b1-b0)*fy;
  var a0=data[i00+3]+(data[i10+3]-data[i00+3])*fx;
  var a1=data[i01+3]+(data[i11+3]-data[i01+3])*fx;
  var a=a0+(a1-a0)*fy;
  return [r,g,b,a];
}

function gaussSolve(A,b){
  var n=b.length, M=[];
  for(var i=0;i<n;i++){ M.push(A[i].slice().concat([b[i]])); }
  for(var c=0;c<n;c++){
    var piv=c, mv=Math.abs(M[c][c]);
    for(var r=c+1;r<n;r++){ var av=Math.abs(M[r][c]); if(av>mv){mv=av;piv=r;} }
    if(piv!==c){ var t=M[c]; M[c]=M[piv]; M[piv]=t; }
    var pv=M[c][c]; if(Math.abs(pv)<1e-12) pv=1e-12;
    for(var j=c;j<=n;j++) M[c][j]/=pv;
    for(var r2=0;r2<n;r2++){ if(r2===c) continue; var f=M[r2][c]; if(f!==0){ for(var j2=c;j2<=n;j2++) M[r2][j2]-=f*M[c][j2]; } }
  }
  var x=[]; for(var i2=0;i2<n;i2++) x.push(M[i2][n]); return x;
}
function solveHomography(src,dst){
  var A=[], b=[];
  for(var i=0;i<4;i++){
    var u=src[i].u, v=src[i].v, x=dst[i].x, y=dst[i].y;
    A.push([u,v,1,0,0,0,-u*x,-v*x]); b.push(x);
    A.push([0,0,0,u,v,1,-u*y,-v*y]); b.push(y);
  }
  var h=gaussSolve(A,b);
  return {a:h[0],b:h[1],c:h[2],d:h[3],e:h[4],f:h[5],g:h[6],h_:h[7]};
}
function perspectiveProcess(data,w,h,opts){
  opts=opts||{};
  var corners=opts.corners;
  var dst= corners || [ {x:0,y:0},{x:w-1,y:0},{x:w-1,y:h-1},{x:0,y:h-1} ];
  var src=[{u:0,v:0},{u:1,v:0},{u:1,v:1},{u:0,v:1}];
  var H=solveHomography(src,dst);
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var Aa=(H.a - x*H.g), Ba=(H.b - x*H.h_), Ca=(x - H.c);
    var Ad=(H.d - y*H.g), Bd=(H.e - y*H.h_), Cd=(y - H.f);
    var det=Aa*Bd - Ba*Ad;
    var i=(y*w+x)*4;
    if(Math.abs(det)<1e-12){ out[i+3]=0; continue; }
    var u=(Ca*Bd - Ba*Cd)/det;
    var v=(Aa*Cd - Ca*Ad)/det;
    if(!isFinite(u)||!isFinite(v)||u<-0.01||u>1.01||v<-0.01||v>1.01){ out[i+3]=0; continue; }
    var s=bsample(data,w,h,u*(w-1),v*(h-1));
    out[i]=s[0];out[i+1]=s[1];out[i+2]=s[2];out[i+3]=255;
  }
  return out;
}

var EXPORTS={perspectiveProcess:perspectiveProcess,solveHomography:solveHomography};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PerspectiveForgePure = EXPORTS; }
